function MidFestivalBtnFightBehavior:OnClick()
    if not self._IsUnlock then
        local unlockLevel = self._activityMidFestivalComponent:GetRecordUnlockLevel()
        local name = self._activityMidFestivalComponent:GetMainQuestName(unlockLevel)
        GameUtils.Toast(localize("通关_name_后解锁", {_name_ = {name}}))
        return
    end
    
    if not self._activityMidFestivalComponent:IsActive() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    local moduleId = ActivityMidFestivalMgr:GetMidFestivalMainDialogId()
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local info = homeDojo.entranceConf[self.config.index]
    UIModule.OpenDialog({
        id = info.moduleId
    },{
        { id = moduleId }
    })
end
