--region private

function MidFestivalBtnFightBehavior:InitData()
    self._IsUnlock = self._activityMidFestivalComponent:IsRecordUnlock()
    self._IsActive = self._activityMidFestivalComponent:IsActive()
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local info = homeDojo.entranceConf[self.config.index]
    self.config.id = info.id
    self.config.vo = ActivityMidFestivalMgr:LoadMainEntryVoById(self.config.id)
end

function MidFestivalBtnFightBehavior:RefreshUI()
    if not string.isEmpty(self.config.vo.name) then
        CfUtils.FillText(self.TabNode.transform:Find("Text").gameObject, self.config.vo.name)
    end
    CfUtils.FillText(self.Lock.transform:Find("Text").gameObject, localize("未解锁"))
    if not string.isEmpty(self.config.vo.unlockPicture) then
        CfUtils.FillImage(self.ImgFight, self.config.vo.unlockPicture)
    end
    if not string.isEmpty(self.config.vo.lockPicture) then
        CfUtils.FillImage(self.ImgFightLock, self.config.vo.lockPicture)
    end

    self:RefreshStatus()
end

function MidFestivalBtnFightBehavior:RefreshStatus()
    CfUtils.SetActive(self.ImgFight, self._IsActive and self._IsUnlock)
    CfUtils.SetActive(self.ImgFightLock, not self._IsActive or not self._IsUnlock)
    CfUtils.SetActive(self.Lock, not self._IsActive or not self._IsUnlock)
end
